type ForgeCapabilityHint = "issues" | "pulls" | "reviews" | "approvals" | "merge-trains" | "required-checks" | "draft-prs" | "assignees" | "releases" | "project-boards" | "milestones" | "batch-branch-prs" | "identity" | "pr-files" | "clone" | (string & {});
